package jp.nw.controller;
import java.io.*;import java.sql.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;import javax.servlet.annotation.*;import javax.servlet.http.*;import jp.nw.entity.*;import jp.nw.model.ScheduleEventLogic;import jp.nw.parts.DBBase;
@WebServlet("/CalendarExchange") @MultipartConfig(maxFileSize=2_097_152)
public class CalendarExchangeController extends HttpServlet{
 protected void doGet(HttpServletRequest q,HttpServletResponse s)throws IOException{UserEntity u=(UserEntity)q.getSession().getAttribute("loginUser");s.setContentType("text/calendar; charset=UTF-8");s.setHeader("Content-Disposition","attachment; filename=schedule.ics");PrintWriter w=s.getWriter();w.println("BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//NW Project//Schedule//JA");DBBase db=new DBBase();try(Connection c=db.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM schedule_event WHERE user_id=? ORDER BY start_at")){p.setString(1,u.getUserId());try(ResultSet r=p.executeQuery()){while(r.next()){w.println("BEGIN:VEVENT");w.println("UID:"+r.getLong("event_id")+"@nwproject");w.println("DTSTART:"+dt(r.getTimestamp("start_at").toLocalDateTime()));w.println("DTEND:"+dt(r.getTimestamp("end_at").toLocalDateTime()));w.println("SUMMARY:"+esc(r.getString("title")));w.println("DESCRIPTION:"+esc(r.getString("description")));w.println("END:VEVENT");}}}catch(SQLException e){throw new IOException(e);}w.println("END:VCALENDAR");}
 protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException,javax.servlet.ServletException{UserEntity u=(UserEntity)q.getSession().getAttribute("loginUser");List<String> lines=new BufferedReader(new InputStreamReader(q.getPart("calendarFile").getInputStream(),java.nio.charset.StandardCharsets.UTF_8)).lines().toList();Map<String,String> event=null;int count=0;ScheduleEventLogic logic=new ScheduleEventLogic();for(String line:lines){if(line.equals("BEGIN:VEVENT"))event=new HashMap<>();else if(line.equals("END:VEVENT")&&event!=null){try{LocalDateTime start=parse(event.get("DTSTART")),end=parse(event.get("DTEND"));logic.create(ScheduleEventEntity.builder().userId(u.getUserId()).title(event.getOrDefault("SUMMARY","取込予定")).description(event.getOrDefault("DESCRIPTION","")).startAt(start).endAt(end).allDay(false).color("#1a73e8").visibility("PRIVATE").build());count++;}catch(Exception ignored){}event=null;}else if(event!=null&&line.contains(":")){int x=line.indexOf(':');String key=line.substring(0,x).split(";")[0];event.put(key,line.substring(x+1).replace("\\n","\n").replace("\\,",","));}}q.getSession().setAttribute("scheduleFlash",count+"件の予定を取り込みました。");s.sendRedirect(q.getContextPath()+"/OpenCalender");}
 private LocalDateTime parse(String v){if(v==null)throw new IllegalArgumentException();if(v.length()==8)return LocalDate.parse(v,DateTimeFormatter.BASIC_ISO_DATE).atStartOfDay();String clean=v.endsWith("Z")?v.substring(0,v.length()-1):v;return LocalDateTime.parse(clean,DateTimeFormatter.ofPattern("yyyyMMdd'T'HHmmss"));}private String dt(LocalDateTime d){return d.format(DateTimeFormatter.ofPattern("yyyyMMdd'T'HHmmss"));}private String esc(String s){return s==null?"":s.replace("\\","\\\\").replace("\n","\\n").replace(",","\\,").replace(";","\\;");}
}
